{
  "$schema": "https://openapi.vercel.sh/vercel.json",
  "buildCommand": "",
  "installCommand": "",
  "outputDirectory": "site",
  "framework": null,
  "cleanUrls": true,
  "trailingSlash": false,
  "redirects": [],
  "rewrites": [
    {
      "source": "/thank-you/",
      "destination": "/thank-you.html"
    },
    {
      "source": "/examples/castos-auto-repair",
      "destination": "/examples/castos-auto-repair/index.html"
    },
    {
      "source": "/examples/castos-auto-repair/",
      "destination": "/examples/castos-auto-repair/index.html"
    },
    {
      "source": "/examples/riverside-lawn",
      "destination": "/examples/riverside-lawn/index.html"
    },
    {
      "source": "/examples/riverside-lawn/",
      "destination": "/examples/riverside-lawn/index.html"
    },
    {
      "source": "/examples/summit-comfort-hvac",
      "destination": "/examples/summit-comfort-hvac/index.html"
    },
    {
      "source": "/examples/summit-comfort-hvac/",
      "destination": "/examples/summit-comfort-hvac/index.html"
    },
    {
      "source": "/examples/heritage-home-partners",
      "destination": "/examples/heritage-home-partners/index.html"
    },
    {
      "source": "/examples/heritage-home-partners/",
      "destination": "/examples/heritage-home-partners/index.html"
    }
  ],
  "headers": [
    {
      "source": "/(.*)",
      "headers": [
        { "key": "X-Frame-Options", "value": "SAMEORIGIN" },
        { "key": "X-Content-Type-Options", "value": "nosniff" },
        { "key": "Referrer-Policy", "value": "strict-origin-when-cross-origin" }
      ]
    }
  ]
}

// Vercel Web Analytics + Speed Insights (static HTML)
(function () {
  window.va = window.va || function () { (window.vaq = window.vaq || []).push(arguments); };
  window.si = window.si || function () { (window.siq = window.siq || []).push(arguments); };

  function load(src) {
    var s = document.createElement('script');
    s.defer = true;
    s.src = src;
    document.head.appendChild(s);
  }

  load('/_vercel/insights/script.js');
  load('/_vercel/speed-insights/script.js');
})();

@import url('https://fonts.googleapis.com/css2?family=Pacifico&display=swap');

*,
*::before,
*::after {
    box-sizing: border-box;
}

html,
body {
    overflow-x: hidden;
    max-width: 100%;
    width: 100%;
}

img,
svg,
video,
iframe {
    max-width: 100%;
}

.font-castos-script {
    font-family: 'Pacifico', 'Brush Script MT', cursive;
}

.text-castos-red { color: #E31E24; }
.bg-castos-red { background-color: #E31E24; }
.border-castos-red { border-color: #E31E24; }
.hover\:bg-castos-red-dark:hover { background-color: #C41A1F; }

.castos-nav-active { color: #E31E24; font-weight: 600; }
.castos-card:hover { border-color: #E31E24; }

.castos-ribbon {
    display: inline-block;
    background-color: #E31E24;
    color: #fff;
    font-weight: 800;
    letter-spacing: 0.12em;
    padding: 0.25rem 0.625rem;
    font-size: 0.7rem;
    line-height: 1.2;
    max-width: 100%;
}

.castos-faith {
    font-family: Georgia, 'Times New Roman', serif;
    font-style: italic;
    font-size: 0.875rem;
    color: #1a1a1a;
    line-height: 1.3;
}

.castos-service-ribbon {
    display: inline-block;
    background-color: #E31E24;
    color: #fff;
    font-weight: 700;
    font-size: 0.65rem;
    padding: 0.3rem 0.75rem 0.35rem;
    margin-top: 0.25rem;
    border-radius: 0 0 999px 999px / 0 0 12px 12px;
    letter-spacing: 0.02em;
    line-height: 1.2;
    max-width: 100%;
}

.castos-wordmark {
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 0;
    max-width: 100%;
}

.castos-wordmark--left {
    align-items: center;
}

@media (min-width: 640px) {
    .castos-wordmark--left {
        align-items: flex-start;
    }
}

.castos-banner-wrap {
    width: 100%;
    max-width: 100%;
    overflow: hidden;
    line-height: 0;
}

.castos-banner {
    display: block;
    width: 100%;
    height: auto;
    max-width: 100%;
}

.castos-brand-lockup {
    display: flex;
    align-items: center;
    gap: 0.625rem;
    min-width: 0;
    overflow: visible;
}

.castos-brand-lockup img {
    flex-shrink: 0;
}

.castos-wordmark-header {
    display: block;
    height: 2.75rem;
    width: auto;
    max-width: none;
    object-fit: contain;
    object-position: left center;
}

.castos-badge {
    display: block;
    border-radius: 50%;
    object-fit: contain;
    background-color: #ffffff;
    padding: 2px;
}

.castos-badge--hero {
    border-radius: 50%;
    object-fit: contain;
    padding: 0.75rem;
    background-color: #ffffff;
    box-sizing: border-box;
}

header .max-w-3xl {
    overflow: visible;
}

.castos-photo {
    display: block;
    width: 100%;
    height: auto;
    border: 2px solid #111111;
    border-radius: 0.5rem;
    object-fit: cover;
}

.castos-photo-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.75rem;
    width: 100%;
    max-width: 100%;
}

.castos-review {
    border-left: 3px solid #E31E24;
    padding: 0.75rem 0 0.75rem 1rem;
    color: #3f3f46;
    line-height: 1.5;
}

.castos-review cite {
    display: block;
    margin-top: 0.5rem;
    font-style: normal;
    font-size: 0.75rem;
    color: #71717a;
}

@media (max-width: 480px) {
    .castos-photo-grid {
        grid-template-columns: 1fr;
    }
}
